class Solution {
public:
    bool isAlienSorted(vector<string>& words, string order) {
        vector<int> rank(26);
        for (int i = 0; i < 26; ++i) rank[order[i] - 'a'] = i;
        for (int i = 0; i < (int)words.size() - 1; ++i) {
            const string& w1 = words[i];
            const string& w2 = words[i + 1];
            int min_len = min(w1.size(), w2.size());
            bool diff = false;
            for (int k = 0; k < min_len; ++k) {
                if (w1[k] != w2[k]) {
                    if (rank[w1[k] - 'a'] > rank[w2[k] - 'a']) return false;
                    diff = true;
                    break;
                }
            }
            if (!diff && w1.size() > w2.size()) return false;
        }
        return true;
    }
};

class Solution {
    public boolean isAlienSorted(String[] words, String order) {
        int[] rank = new int[26];
        for (int i = 0; i < 26; i++) rank[order.charAt(i) - 'a'] = i;
        for (int i = 0; i < words.length - 1; i++) {
            String w1 = words[i];
            String w2 = words[i + 1];
            int minLen = Math.min(w1.length(), w2.length());
            boolean diff = false;
            for (int k = 0; k < minLen; k++) {
                if (w1.charAt(k) != w2.charAt(k)) {
                    if (rank[w1.charAt(k) - 'a'] > rank[w2.charAt(k) - 'a']) return false;
                    diff = true;
                    break;
                }
            }
            if (!diff && w1.length() > w2.length()) return false;
        }
        return true;
    }
}

